/// Generates the first `len` bits of `w = limit of mu^j(1)` by iterating the
/// uniform morphism `1 -> 1110`, `0 -> 1101`.
pub fn mu_word_by_substitution(len: usize) -> Vec<bool> {
    if len == 0 {
        return Vec::new();
    }
    let mut word = vec![true];
    while word.len() < len {
        let mut next = Vec::with_capacity(word.len() * 4);
        for &bit in &word {
            if bit {
                next.extend_from_slice(&[true, true, true, false]);
            } else {
                next.extend_from_slice(&[true, true, false, true]);
            }
        }
        word = next;
    }
    word.truncate(len);
    word
}

/// Computes `w[n]` directly from the base-4 symbol recurrence:
/// `w[4n] = 1`, `w[4n+1] = 1`, `w[4n+2] = w[n]`, `w[4n+3] = 1 - w[n]`.
pub fn mu_bit_by_recurrence(mut n: usize) -> bool {
    let mut flip = false;
    while n > 0 {
        match n & 3 {
            0 | 1 => return !flip,
            2 => n >>= 2,
            3 => {
                flip = !flip;
                n >>= 2;
            }
            _ => unreachable!(),
        }
    }
    !flip
}

/// Generates the periodic control word `(1110)^infinity` truncated to `len`.
pub fn periodic_control_word(len: usize) -> Vec<bool> {
    (0..len).map(|i| (i & 3) != 3).collect()
}

/// Checks that `bits` matches the base-4 recurrence at every index and that
/// every non-empty prefix satisfies `3^(r_k) > 2^k` and the block-count bound.
pub fn verify_word_and_all_prefix_survival(bits: &[bool]) -> Result<(), String> {
    if bits.is_empty() {
        return Err("empty parity word".into());
    }
    let three = BigUint::from(3u32);
    let mut odd_steps = 0usize;
    let mut pow3 = BigUint::one();
    let mut pow2 = BigUint::one();
    for (idx, &bit) in bits.iter().enumerate() {
        if bit != mu_bit_by_recurrence(idx) {
            return Err(format!(
                "substitution word and base-4 recurrence disagree at index {idx}"
            ));
        }
        if bit {
            odd_steps += 1;
            pow3 *= &three;
        }
        pow2 <<= 1usize;
        let k = idx + 1;
        if pow3 <= pow2 {
            return Err(format!("coefficient crossing at prefix length {k}"));
        }
        // Check the algebraic block decomposition k = 4*q + s, s in 1..=4.
        let q = (k - 1) / 4;
        let s = k - 4 * q;
        let expected_min_part = match s {
            1 => 1,
            2 | 3 => 2,
            4 => 3,
            _ => unreachable!(),
        };
        if odd_steps < 3 * q + expected_min_part {
            return Err(format!(
                "prefix length {k} violates block odd-step lower bound"
            ));
        }
        if s == 4 && odd_steps != 3 * (q + 1) {
            return Err(format!(
                "full block prefix {k} has {odd_steps} odd steps instead of {}",
                3 * (q + 1)
            ));
        }
    }
    Ok(())
}

/// Verifies `(1 - z^4) * (F(z) - (z^2 - z^3) F(z^4)) = 1 + z + z^3` in `Z[[z]]`
/// up to degree `max_deg`.
pub fn verify_mahler_power_series(bits: &[bool], max_deg: usize) -> Result<(), String> {
    if bits.len() <= max_deg {
        return Err("insufficient word length for power-series check".into());
    }
    // G[i] = [z^i] (F(z) - (z^2 - z^3) F(z^4))
    let mut g = vec![0i64; max_deg + 1];
    for i in 0..=max_deg {
        g[i] += i64::from(bits[i]);
        if i >= 2 && (i - 2).is_multiple_of(4) {
            g[i] -= i64::from(bits[(i - 2) / 4]);
        }
        if i >= 3 && (i - 3).is_multiple_of(4) {
            g[i] += i64::from(bits[(i - 3) / 4]);
        }
    }
    for i in 0..=max_deg {
        let lhs = g[i] - if i >= 4 { g[i - 4] } else { 0 };
        let rhs = match i {
            0 | 1 | 3 => 1,
            _ => 0,
        };
        if lhs != rhs {
            return Err(format!(
                "Mahler power-series identity fails at degree {i}: got {lhs}, expected {rhs}"
            ));
        }
    }
    Ok(())
}

/// Independent residue computation from the positions `d_i` of the odd steps:
/// `x(w_<K) = -sum_{i=0}^{r_K - 1} 2^(d_i) / 3^(i+1) (mod 2^K)`.
/// Uses neither `AffineMap` nor `Cylinder`.
pub fn residue_by_parity_positions(bits: &[bool]) -> BigUint {
    let k = bits.len();
    if k == 0 {
        return BigUint::zero();
    }
    let modulus = BigUint::one() << k;
    let inv3 = BigUint::from(3u32)
        .modinv(&modulus)
        .expect("3 is invertible modulo 2^K");
    let mut inv3_pow = BigUint::one();
    let mut sum = BigUint::zero();
    for (pos, &odd) in bits.iter().enumerate() {
        if odd {
            inv3_pow = (&inv3_pow * &inv3) % &modulus;
            let term = ((BigUint::one() << pos) * &inv3_pow) % &modulus;
            sum = (sum + term) % &modulus;
        }
    }
    (&modulus - sum) % &modulus
}

/// Evaluates `F_2(16/27) = sum_{n >= 0} w[n] (16/27)^n (mod 2^K)`.
pub fn f2_series_mod_2k(bits: &[bool], k_bits: usize) -> BigUint {
    let modulus = BigUint::one() << k_bits;
    let inv27 = BigUint::from(27u32)
        .modinv(&modulus)
        .expect("27 is invertible modulo 2^K");
    let z = (BigUint::from(16u32) * inv27) % &modulus;
    let terms = k_bits.div_ceil(4);
    let mut z_pow = BigUint::one();
    let mut sum = BigUint::zero();
    for &bit in bits.iter().take(terms) {
        if bit {
            sum = (sum + &z_pow) % &modulus;
        }
        z_pow = (&z_pow * &z) % &modulus;
    }
    sum
}

/// Evaluates the right-hand side of the Mahler functional equation
/// `(1 + z + z^3)/(1 - z^4) + (z^2 - z^3) F_2(z^4)` at `z = 16/27 (mod 2^K)`.
pub fn f2_functional_equation_rhs_mod_2k(bits: &[bool], k_bits: usize) -> BigUint {
    let modulus = BigUint::one() << k_bits;
    let inv27 = BigUint::from(27u32)
        .modinv(&modulus)
        .expect("27 is invertible modulo 2^K");
    let z = (BigUint::from(16u32) * inv27) % &modulus;
    let z2 = (&z * &z) % &modulus;
    let z3 = (&z2 * &z) % &modulus;
    let z4 = (&z2 * &z2) % &modulus;
    let one_minus_z4 = (&modulus + BigUint::one() - &z4) % &modulus;
    let inv_one_minus_z4 = one_minus_z4
        .modinv(&modulus)
        .expect("1 - (16/27)^4 is odd, hence invertible modulo 2^K");
    let a_val = ((BigUint::one() + &z + &z3) % &modulus * inv_one_minus_z4) % &modulus;
    let b_val = (&modulus + &z2 - &z3) % &modulus;

    // Evaluate F_2(z^4) mod 2^K: each step multiplies by z^4 = (16/27)^4, which adds 16 bits of 2-adic valuation.
    let terms = k_bits.div_ceil(16);
    let mut z4_pow = BigUint::one();
    let mut f_z4 = BigUint::zero();
    for &bit in bits.iter().take(terms) {
        if bit {
            f_z4 = (f_z4 + &z4_pow) % &modulus;
        }
        z4_pow = (&z4_pow * &z4) % &modulus;
    }
    (a_val + b_val * f_z4) % &modulus
}

/// Computes `x(w) = -23/11 + (4/27) * F_2(16/27) (mod 2^K)`.
pub fn mahler_seed_mod_2k(f2_val: &BigUint, k_bits: usize) -> BigUint {
    let modulus = BigUint::one() << k_bits;
    let inv11 = BigUint::from(11u32)
        .modinv(&modulus)
        .expect("11 is invertible modulo 2^K");
    let inv27 = BigUint::from(27u32)
        .modinv(&modulus)
        .expect("27 is invertible modulo 2^K");
    let neg23_over_11 = ((&modulus - (BigUint::from(23u32) % &modulus)) * inv11) % &modulus;
    let four_over_27_f2 = (((BigUint::from(4u32) * inv27) % &modulus) * f2_val) % &modulus;
    (neg23_over_11 + four_over_27_f2) % &modulus
}

/// Homogenised prefix sum `preS(a, b, L) = sum_{q=0}^{L-1} w[q] a^q b^(L-1-q)`.
pub fn homogenised_prefix_sum(bits: &[bool], a: &BigInt, b: &BigInt, len: usize) -> BigInt {
    let mut acc = BigInt::zero();
    let mut a_pow = BigInt::one();
    for &bit in bits.iter().take(len) {
        acc *= b;
        if bit {
            acc += &a_pow;
        }
        a_pow *= a;
    }
    acc
}

/// Homogenised geometric sum `geomS(a, b, L) = sum_{q=0}^{L-1} a^q b^(L-1-q)`.
pub fn homogenised_geom_sum(a: &BigInt, b: &BigInt, len: usize) -> BigInt {
    let mut acc = BigInt::zero();
    let mut a_pow = BigInt::one();
    for _ in 0..len {
        acc = acc * b + &a_pow;
        a_pow *= a;
    }
    acc
}

fn evaluate_checkpoint(bits: &[bool], k_bits: usize) -> Result<CheckpointRow, String> {
    if !k_bits.is_multiple_of(4) || bits.len() < k_bits {
        return Err(format!("invalid checkpoint length {k_bits}"));
    }
    let prefix_slice = &bits[..k_bits];
    verify_word_and_all_prefix_survival(prefix_slice)?;

    let prefix = ParityPrefix::from_bits(prefix_slice.to_vec());
    let affine = AffineMap::from_prefix(&prefix);
    let cylinder = Cylinder::from_prefix(&prefix);

    let residue_affine_inverse = residue_by_inverse(&affine);
    let residue_cylinder_lift = cylinder.residue().clone();
    let residue_parity_positions = residue_by_parity_positions(prefix_slice);

    let f2_mod_2k = f2_series_mod_2k(bits, k_bits);
    let f2_fe = f2_functional_equation_rhs_mod_2k(bits, k_bits);
    let f2_functional_equation_matches = f2_mod_2k == f2_fe;
    let residue_mahler_reduction = mahler_seed_mod_2k(&f2_mod_2k, k_bits);

    // Check the exact block-cocycle identity:
    // 11 * c(w_<4L) = 23 * (27^L - 16^L) - 44 * preS(16, 27, L).
    let blocks = k_bits / 4;
    let pre_s = homogenised_prefix_sum(bits, &BigInt::from(16u32), &BigInt::from(27u32), blocks);
    let lhs_cocycle = BigInt::from(11u32) * BigInt::from(affine.offset().clone());
    let pow27 = Pow::pow(&BigInt::from(27u32), blocks);
    let pow16 = Pow::pow(&BigInt::from(16u32), blocks);
    let rhs_cocycle = BigInt::from(23u32) * (pow27 - pow16) - BigInt::from(44u32) * pre_s;
    let block_cocycle_matches =
        lhs_cocycle == rhs_cocycle && closed_form_offset(prefix_slice) == *affine.offset();

    // Direct-iteration oracle on the unique residue x_K in [0, 2^K).
    let emitted = collatz::parity_vector(&residue_affine_inverse, k_bits);
    let image = collatz::t_iter(&residue_affine_inverse, k_bits);
    let direct_iteration_matches =
        emitted == prefix_slice && (&image << k_bits) == affine.numerator(&residue_affine_inverse);

    if residue_affine_inverse != residue_cylinder_lift
        || residue_affine_inverse != residue_parity_positions
        || residue_affine_inverse != residue_mahler_reduction
        || !f2_functional_equation_matches
        || !block_cocycle_matches
        || !direct_iteration_matches
    {
        return Err(format!(
            "checkpoint K={k_bits}: independent residue oracles disagree"
        ));
    }

    Ok(CheckpointRow {
        k_bits,
        odd_steps: affine.odd_steps(),
        all_prefixes_survive: true,
        f2_mod_2k,
        f2_functional_equation_matches,
        residue_affine_inverse,
        residue_cylinder_lift,
        residue_parity_positions,
        residue_mahler_reduction,
        block_cocycle_matches,
        direct_iteration_matches,
    })
}

fn evaluate_periodic_control(k_bits: usize) -> Result<PeriodicControlRow, String> {
    let control_bits = periodic_control_word(k_bits + 64);
    let prefix = ParityPrefix::from_bits(control_bits[..k_bits].to_vec());
    let cylinder = Cylinder::from_prefix(&prefix);
    let modulus = cylinder.modulus();
    let positive_seed = cylinder.least_member_at_least(&BigUint::from(2u32));

    // Check 11 * positive_seed + 19 == 0 (mod 2^K), i.e., x = -19/11 in Z_2.
    let eleven_n_plus_19 = &positive_seed * 11u32 + 19u32;
    let matches_minus_19_over_11 = (&eleven_n_plus_19 % &modulus).is_zero()
        && residue_by_parity_positions(&control_bits[..k_bits]) == *cylinder.residue();

    let emitted = collatz::parity_vector(&positive_seed, k_bits);
    let direct_iteration_matches_prefix = emitted == control_bits[..k_bits];
    let iterated = collatz::t_iter(&positive_seed, k_bits);
    let iterated_value_exceeds_seed = iterated > positive_seed;

    // Locate the exact step >= k_bits where the positive integer seed diverges from (1110)^infinity.
    let mut x = positive_seed.clone();
    let mut step = 0usize;
    let first_divergence_step = loop {
        let odd = collatz::is_odd(&x);
        if odd != ((step & 3) != 3) {
            break step;
        }
        x = collatz::t_step(&x);
        step += 1;
        if step > k_bits + 64 {
            return Err(format!(
                "periodic control seed at K={k_bits} did not diverge within expected horizon"
            ));
        }
    };

    if !matches_minus_19_over_11
        || !direct_iteration_matches_prefix
        || !iterated_value_exceeds_seed
        || first_divergence_step < k_bits
    {
        return Err(format!("periodic control invariant failed at K={k_bits}"));
    }

    Ok(PeriodicControlRow {
        k_bits,
        odd_steps: prefix.odd_count(),
        positive_seed,
        matches_minus_19_over_11,
        direct_iteration_matches_prefix,
        iterated_value_exceeds_seed,
        first_divergence_step,
    })
}

fn bigint_gcd(a: &BigInt, b: &BigInt) -> BigInt {
    let mut x = a.magnitude().clone();
    let mut y = b.magnitude().clone();
    while !y.is_zero() {
        let r = x % &y;
        x = y;
        y = r;
    }
    BigInt::from(x)
}

fn two_adic_valuation_bigint(n: &BigInt) -> usize {
    let mag = n.magnitude();
    assert!(!mag.is_zero(), "zero has infinite 2-adic valuation");
    usize::try_from(mag.trailing_zeros().unwrap_or(0)).expect("valuation fits in usize")
}

/// Exact fraction-free rational Gaussian elimination over `BigInt` to compute
/// the nullspace of a matrix with `rows.len()` equations and `cols` unknowns.
fn exact_integer_nullspace(rows: &[Vec<BigInt>], cols: usize) -> Vec<Vec<BigInt>> {
    // Represent rational matrix entries with a common positive denominator per row,
    // reduced by row GCD after each elimination step.
    let mut mat = rows.to_vec();
    let mut pivot_cols = Vec::new();
    let mut r = 0usize;
    for c in 0..cols {
        let Some(piv) = (r..mat.len()).find(|&i| !mat[i][c].is_zero()) else {
            continue;
        };
        mat.swap(r, piv);
        if mat[r][c] < BigInt::zero() {
            for val in &mut mat[r] {
                *val = -&*val;
            }
        }
        let piv_val = mat[r][c].clone();
        for i in 0..mat.len() {
            if i == r || mat[i][c].is_zero() {
                continue;
            }
            let factor = mat[i][c].clone();
            for j in 0..cols {
                mat[i][j] = &mat[i][j] * &piv_val - &mat[r][j] * &factor;
            }
            let mut row_gcd = BigInt::zero();
            for val in &mat[i] {
                if !val.is_zero() {
                    row_gcd = bigint_gcd(&row_gcd, val);
                }
            }
            if row_gcd > BigInt::one() {
                for val in &mut mat[i] {
                    *val /= &row_gcd;
                }
            }
        }
        pivot_cols.push(c);
        r += 1;
        if r == mat.len() {
            break;
        }
    }

    let free_cols: Vec<usize> = (0..cols).filter(|c| !pivot_cols.contains(c)).collect();
    let mut basis = Vec::with_capacity(free_cols.len());
    for &fc in &free_cols {
        // Common multiplier is the product of pivot entries.
        let mut prod = BigInt::one();
        for (row_idx, &pc) in pivot_cols.iter().enumerate() {
            prod *= &mat[row_idx][pc];
        }
        let mut vec = vec![BigInt::zero(); cols];
        vec[fc] = prod.clone();
        for (row_idx, &pc) in pivot_cols.iter().enumerate() {
            vec[pc] = -(&mat[row_idx][fc] * (&prod / &mat[row_idx][pc]));
        }
        let mut g = BigInt::zero();
        for val in &vec {
            if !val.is_zero() {
                g = bigint_gcd(&g, val);
            }
        }
        if g > BigInt::one() {
            for val in &mut vec {
                *val /= &g;
            }
        }
        if let Some(first_nz) = vec.iter().find(|v| !v.is_zero()) {
            if *first_nz < BigInt::zero() {
                for val in &mut vec {
                    *val = -&*val;
                }
            }
        }
        basis.push(vec);
    }
    basis
}

fn poly_degree(coeffs: &[BigInt]) -> usize {
    coeffs.iter().rposition(|c| !c.is_zero()).unwrap_or(0)
}

/// Evaluates `[z^k] (p0(z) + p1(z) F(z))` from exact integer coefficients.
fn pade_series_coeff(p0: &[BigInt], p1: &[BigInt], bits: &[bool], k: usize) -> BigInt {
    let mut acc = if k < p0.len() {
        p0[k].clone()
    } else {
        BigInt::zero()
    };
    for (i, coeff) in p1.iter().enumerate() {
        if k >= i && bits[k - i] {
            acc += coeff;
        }
    }
    acc
}

/// Homogenised polynomial `b^deg * p(a/b) = sum_{i=0..deg} c_i a^i b^(deg - i)`.
fn homogenised_poly(coeffs: &[BigInt], deg: usize, a: &BigInt, b: &BigInt) -> BigInt {
    let mut total = BigInt::zero();
    for (i, coeff) in coeffs.iter().enumerate().take(deg + 1) {
        if !coeff.is_zero() {
            let term = coeff * Pow::pow(a, i) * Pow::pow(b, deg - i);
            total += term;
        }
    }
    total
}

fn analyze_pade_degree(bits: &[bool], m: usize) -> Result<PadeCandidateRow, String> {
    let target_order = 2 * m + 1;
    let cols = 2 * m + 2;
    let mut rows = Vec::with_capacity(target_order);
    for j in 0..target_order {
        let mut row = vec![BigInt::zero(); cols];
        if j <= m {
            row[j] = BigInt::one();
        }
        for i in 0..=m {
            if j >= i && bits[j - i] {
                row[m + 1 + i] = BigInt::one();
            }
        }
        rows.push(row);
    }
    let basis = exact_integer_nullspace(&rows, cols);
    if basis.is_empty() {
        return Err(format!(
            "m={m}: empty Padé nullspace at order {target_order}"
        ));
    }
    let nullspace_dim_at_2m_plus_1 = basis.len();

    // Choose the basis vector with minimal common z-shift (or highest order on ties).
    let chosen = basis
        .iter()
        .min_by_key(|v| {
            let p0 = &v[..=m];
            let p1 = &v[m + 1..];
            let shift0 = p0.iter().position(|c| !c.is_zero()).unwrap_or(m + 1);
            let shift1 = p1.iter().position(|c| !c.is_zero()).unwrap_or(m + 1);
            shift0.min(shift1)
        })
        .expect("non-empty basis");

    let p0: Vec<BigInt> = chosen[..=m].to_vec();
    let p1: Vec<BigInt> = chosen[m + 1..].to_vec();

    // Independent verification by series coefficient arithmetic.
    let mut vanishing_order = 0usize;
    while vanishing_order < bits.len() - m {
        let c = pade_series_coeff(&p0, &p1, bits, vanishing_order);
        if !c.is_zero() {
            break;
        }
        vanishing_order += 1;
    }
    if vanishing_order < target_order {
        return Err(format!(
            "m={m}: vanishing order {vanishing_order} < {target_order}"
        ));
    }
    let leading_coeff_val = pade_series_coeff(&p0, &p1, bits, vanishing_order);
    let leading_coeff_v2 = two_adic_valuation_bigint(&leading_coeff_val);
    let leading_coeff_is_odd = leading_coeff_v2 == 0;

    // Extract reduced (z-shift free) polynomial pair.
    let shift0 = p0.iter().position(|c| !c.is_zero()).unwrap_or(m + 1);
    let shift1 = p1.iter().position(|c| !c.is_zero()).unwrap_or(m + 1);
    let common_z_shift = shift0.min(shift1);
    let reduced_p0: Vec<BigInt> = p0[common_z_shift..].to_vec();
    let reduced_p1: Vec<BigInt> = p1[common_z_shift..].to_vec();
    let reduced_max_degree = poly_degree(&reduced_p0).max(poly_degree(&reduced_p1));
    let reduced_vanishing_order = vanishing_order - common_z_shift;
    let in_singular_block =
        nullspace_dim_at_2m_plus_1 > 1 || common_z_shift > 0 || reduced_max_degree < m;

    // Check homogenised Padé identity at (a0, b0) = (16, 27):
    // b0^N * P0(a0, b0) + P1(a0, b0) * preS(a0, b0, N + 1) = a0^N * (c * b0^M_deg + a0 * R).
    let a0 = BigInt::from(16u32);
    let b0 = BigInt::from(27u32);
    let p0_hom = homogenised_poly(&reduced_p0, reduced_max_degree, &a0, &b0);
    let p1_hom = homogenised_poly(&reduced_p1, reduced_max_degree, &a0, &b0);
    let pre_s = homogenised_prefix_sum(bits, &a0, &b0, reduced_vanishing_order + 1);
    let lhs_hom = Pow::pow(&b0, reduced_vanishing_order) * &p0_hom + &p1_hom * pre_s;
    let a0_pow_n = Pow::pow(&a0, reduced_vanishing_order);
    if !(&lhs_hom % &a0_pow_n).is_zero() {
        return Err(format!("m={m}: a0^N does not divide homogenised Padé LHS"));
    }
    let q_hom = &lhs_hom / &a0_pow_n;
    let lead_term_hom = &leading_coeff_val * Pow::pow(&b0, reduced_max_degree);
    let rem_mod_a0 = (&q_hom - &lead_term_hom) % &a0;
    let v2_lhs = two_adic_valuation_bigint(&lhs_hom);
    let expected_v2_matches = if leading_coeff_v2 < 4 {
        v2_lhs == 4 * reduced_vanishing_order + leading_coeff_v2
    } else {
        v2_lhs >= 4 * reduced_vanishing_order + 4
    };
    let level0_valuation_verified = rem_mod_a0.is_zero() && expected_v2_matches;
    if !level0_valuation_verified {
        return Err(format!(
            "m={m}: homogenised Padé check failed (rem_mod_a0={rem_mod_a0}, v2_lhs={v2_lhs})"
        ));
    }

    let mut l1_height = BigUint::zero();
    let mut linf_height = BigUint::zero();
    for coeff in p0.iter().chain(p1.iter()) {
        let mag = coeff.magnitude();
        l1_height += mag;
        if mag > &linf_height {
            linf_height = mag.clone();
        }
    }

    // Exact integer height-ledger comparisons:
    // 1. Cancelled-tower asymptotic comparison per 4^k (cubed to clear 1/3 exponents):
    //    2^(4 * (3 * N_red + 2)) > 3^(3 * (3 * M_red + 7)).
    let cancelled_tower_gain_exp2 = 4 * (3 * reduced_vanishing_order + 2);
    let cancelled_tower_cost_exp3 = 3 * (3 * reduced_max_degree + 7);
    let gain_pow2 = BigUint::one() << cancelled_tower_gain_exp2;
    let cost_pow3 = Pow::pow(&BigUint::from(3u32), cancelled_tower_cost_exp3);
    let closes_cancelled_tower_asymptotic = gain_pow2 > cost_pow3;

    // 2. Coarsest integer-tower bound (no fractional exponents, requires odd leading coeff c):
    //    2^(4 * N_red) > 16 * 27^(M_red + 3).
    let coarse_gain = BigUint::one() << (4 * reduced_vanishing_order);
    let coarse_cost =
        BigUint::from(16u32) * Pow::pow(&BigUint::from(27u32), reduced_max_degree + 3);
    let closes_coarse_integer_ledger = leading_coeff_is_odd && coarse_gain > coarse_cost;

    Ok(PadeCandidateRow {
        degree_bound: m,
        nullspace_dim_at_2m_plus_1,
        common_z_shift,
        reduced_max_degree,
        in_singular_block,
        p0_coeffs: p0.iter().map(ToString::to_string).collect(),
        p1_coeffs: p1.iter().map(ToString::to_string).collect(),
        reduced_p0_coeffs: reduced_p0.iter().map(ToString::to_string).collect(),
        reduced_p1_coeffs: reduced_p1.iter().map(ToString::to_string).collect(),
        l1_height,
        linf_height,
        vanishing_order,
        reduced_vanishing_order,
        leading_coeff: leading_coeff_val.to_string(),
        leading_coeff_v2,
        leading_coeff_is_odd,
        power_series_identity_verified: true,
        level0_valuation_verified,
        uncancelled_tower_keeps_odd_denominator: false,
        cancelled_tower_gain_exp2,
        cancelled_tower_cost_exp3,
        closes_cancelled_tower_asymptotic,
        closes_coarse_integer_ledger,
    })
}

fn verify_mahler_tower_summary(bits: &[bool]) -> Result<MahlerTowerSummary, String> {
    let a0 = BigInt::from(16u32);
    let b0 = BigInt::from(27u32);
    let a1 = Pow::pow(&a0, 4usize);
    let b1 = Pow::pow(&b0, 4usize);
    let blocks = 64usize;

    // 1. Verify the homogenised functional equation for preS(16, 27, 4L), 1 <= L <= 64.
    let coeff_geom = Pow::pow(&b0, 3usize) + &a0 * Pow::pow(&b0, 2usize) + Pow::pow(&a0, 3usize);
    let coeff_pres = Pow::pow(&a0, 2usize) * (&b0 - &a0);
    for l in 1..=blocks {
        let lhs = homogenised_prefix_sum(bits, &a0, &b0, 4 * l);
        let rhs = &coeff_geom * homogenised_geom_sum(&a1, &b1, l)
            + &coeff_pres * homogenised_prefix_sum(bits, &a1, &b1, l);
        if lhs != rhs {
            return Err(format!(
                "homogenised functional equation failed at block L={l}"
            ));
        }
    }

    // 2. Verify the backward tower transport from level 0 to level 1 on a 2-adic witness u0/D0.
    let l_max = 64usize;
    let mod0 = Pow::pow(&BigUint::from(16u32), l_max);
    let inv_b0 = BigUint::from(27u32)
        .modinv(&mod0)
        .expect("27 is invertible modulo 16^L");
    let pre_s_max = homogenised_prefix_sum(bits, &a0, &b0, l_max)
        .to_biguint()
        .expect("preS is non-negative");
    let u0_uint = (pre_s_max * mod0_pow(&inv_b0, l_max - 1, &mod0)) % &mod0;
    let u0 = BigInt::from(u0_uint);
    let d0 = BigInt::one();

    // Uncancelled D1 = D0 * a0^2 * (b0 - a0) * (b0^4 - a0^4) has 2-adic valuation 2 * 4 = 8 > 0.
    let uncancelled_d1 =
        &d0 * Pow::pow(&a0, 2usize) * (&b0 - &a0) * (Pow::pow(&b0, 4usize) - Pow::pow(&a0, 4usize));
    let uncancelled_d1_two_adic_valuation = two_adic_valuation_bigint(&uncancelled_d1);

    // Cancelled Delta0 must be divisible by a0^2 = 256, keeping D1 odd.
    let delta0 = (Pow::pow(&b0, 4usize) - Pow::pow(&a0, 4usize)) * &u0 - &d0 * &b0 * &coeff_geom;
    let a0_sq = Pow::pow(&a0, 2usize);
    let cancelled_delta0_divisible_by_a0_sq = (&delta0 % &a0_sq).is_zero();
    if !cancelled_delta0_divisible_by_a0_sq {
        return Err("Delta0 is not divisible by a0^2".into());
    }
    let u1 = Pow::pow(&b0, 3usize) * (&delta0 / &a0_sq);
    let d1 = &d0 * (&b0 - &a0) * (Pow::pow(&b0, 4usize) - Pow::pow(&a0, 4usize));
    if two_adic_valuation_bigint(&d1) != 0 {
        return Err("cancelled D1 is not odd".into());
    }
    let level1_blocks = 15usize;
    for l in 1..=level1_blocks {
        let diff = &u1 * Pow::pow(&b1, l - 1) - &d1 * homogenised_prefix_sum(bits, &a1, &b1, l);
        let mod1 = Pow::pow(&a1, l);
        if !(diff % mod1).is_zero() {
            return Err(format!("level-1 transport divisibility failed at L={l}"));
        }
    }

    let degree1_gain_power_of_two = BigUint::one() << 44usize;
    let degree1_cost_power_of_three = Pow::pow(&BigUint::from(3u32), 30usize);
    let degree1_closes_ledger = degree1_gain_power_of_two > degree1_cost_power_of_three;

    let degree4_coarse_gain_2_pow_56 = BigUint::one() << 56usize;
    let degree4_coarse_cost_16_mul_27_pow_7 =
        BigUint::from(16u32) * Pow::pow(&BigUint::from(27u32), 7usize);
    let degree4_closes_cancelled_ledger =
        degree4_coarse_gain_2_pow_56 > degree4_coarse_cost_16_mul_27_pow_7;

    Ok(MahlerTowerSummary {
        functional_equation_verified_degree: DEFAULT_MAX_BITS,
        homogenised_prefix_verified_blocks: blocks,
        b_poly_zero_order_at_origin: 2,
        uncancelled_d1_two_adic_valuation,
        cancelled_delta0_divisible_by_a0_sq,
        level1_transport_verified_blocks: level1_blocks,
        truncation_exponent_lt_one: BigUint::from(16u32) < BigUint::from(27u32),
        degree1_gain_power_of_two,
        degree1_cost_power_of_three,
        degree1_closes_ledger,
        degree4_coarse_gain_2_pow_56,
        degree4_coarse_cost_16_mul_27_pow_7,
        degree4_closes_cancelled_ledger,
    })
}

fn mod0_pow(base: &BigUint, mut exp: usize, modulus: &BigUint) -> BigUint {
    let mut result = BigUint::one();
    let mut cur = base % modulus;
    while exp > 0 {
        if exp & 1 == 1 {
            result = (result * &cur) % modulus;
        }
        cur = (&cur * &cur) % modulus;
        exp >>= 1;
    }
    result
}

/// Independent check that rejects a perturbed parity word, a wrong affine offset,
/// a wrong modular inverse, or an invalid epistemic status promotion.
pub fn verify_candidate_integrity(
    bits: &[bool],
    claimed_offset: &BigUint,
    claimed_inv3_pow: &BigUint,
    claimed_infinite_orbit_from_finite_check: bool,
) -> Result<(), String> {
    if claimed_infinite_orbit_from_finite_check {
        return Err(
            "invalid epistemic promotion: finite prefix checks cannot establish an infinite positive-integer orbit or theorem"
                .into(),
        );
    }
    verify_word_and_all_prefix_survival(bits)?;
    let k = bits.len();
    let modulus = BigUint::one() << k;
    let odd_steps = bits.iter().filter(|&&b| b).count();
    let pow3 = Pow::pow(&BigUint::from(3u32), odd_steps);
    if ((&pow3 % &modulus) * claimed_inv3_pow) % &modulus != BigUint::one() {
        return Err("incorrect modular inverse for 3^(r_K) mod 2^K".into());
    }
    let true_offset = closed_form_offset(bits);
    if claimed_offset != &true_offset {
        return Err(format!(
            "wrong parity offset: claimed {claimed_offset}, closed form gives {true_offset}"
        ));
    }
    let residue = ((&modulus - (claimed_offset % &modulus)) * claimed_inv3_pow) % &modulus;
    if residue != residue_by_parity_positions(bits) {
        return Err("residue disagrees with independent parity-position sum".into());
    }
    Ok(())
}

/// Re-verifies an entire `MahlerExperiment` outcome against `bits` and rejects
/// any perturbed parity block, wrong offset/residue, wrong modular inverse,
/// or invalid epistemic status promotion.
pub fn verify_mahler_experiment(bits: &[bool], outcome: &MahlerExperiment) -> Result<(), String> {
    verify_word_and_all_prefix_survival(bits)?;
    if outcome.finite_checkpoints_status != Status::VerifiedForFiniteDomain
        || outcome.cancelled_pade_exploration_status != Status::VerifiedForFiniteDomain
    {
        return Err("invalid status: falsely promotes finite checks to an infinite theorem".into());
    }
    if outcome.shift_and_general_divergent_status != Status::Conjectured {
        return Err(
            "invalid status: falsely claims resolution of open shift/divergent-orbit obligations"
                .into(),
        );
    }
    if outcome.uncancelled_tower_status != Status::Refuted
        || outcome.tower_summary.uncancelled_d1_two_adic_valuation == 0
    {
        return Err(
            "invalid status: uncancelled polynomial denominator tower has even D_1 (v_2(D_1) = 8)"
                .into(),
        );
    }
    for row in &outcome.checkpoints {
        let expected = evaluate_checkpoint(bits, row.k_bits)?;
        if row.residue_affine_inverse != expected.residue_affine_inverse {
            return Err(format!(
                "K={}: wrong affine residue (got {}, expected {})",
                row.k_bits, row.residue_affine_inverse, expected.residue_affine_inverse
            ));
        }
        if row.f2_mod_2k != expected.f2_mod_2k {
            return Err(format!(
                "K={}: wrong F_2(16/27) mod 2^K (got {}, expected {})",
                row.k_bits, row.f2_mod_2k, expected.f2_mod_2k
            ));
        }
        if row.residue_mahler_reduction != expected.residue_mahler_reduction
            || row.residue_mahler_reduction != row.residue_affine_inverse
        {
            return Err(format!("K={}: Mahler residue mismatch", row.k_bits));
        }
        if row != &expected {
            return Err(format!("K={}: checkpoint row mismatch", row.k_bits));
        }
    }
    Ok(())
}

/// Runs the bounded Phase 3 Mahler and 2-adic itinerary experiment.
pub fn run_mahler() -> Result<MahlerExperiment, String> {
    let bits = mu_word_by_substitution(DEFAULT_MAX_BITS + 64);
    verify_word_and_all_prefix_survival(&bits)?;
    verify_mahler_power_series(&bits, DEFAULT_MAX_BITS)?;

    let mut checkpoints = Vec::with_capacity(CHECKPOINT_BITS.len());
    for &k_bits in &CHECKPOINT_BITS {
        checkpoints.push(evaluate_checkpoint(&bits, k_bits)?);
    }

    let mut periodic_control = Vec::with_capacity(CHECKPOINT_BITS.len());
    for &k_bits in &CHECKPOINT_BITS {
        periodic_control.push(evaluate_periodic_control(k_bits)?);
    }

    let mut pade_candidates = Vec::with_capacity(MAX_PADE_DEGREE);
    for m in 1..=MAX_PADE_DEGREE {
        pade_candidates.push(analyze_pade_degree(&bits, m)?);
    }

    let tower_summary = verify_mahler_tower_summary(&bits)?;

    Ok(MahlerExperiment {
        schema: "collatz-lab-mahler-v1".into(),
        tool_version: env!("CARGO_PKG_VERSION").into(),
        max_bits: DEFAULT_MAX_BITS,
        max_pade_degree: MAX_PADE_DEGREE,
        prefix_survival_status: Status::ProvenByAlgebra,
        aperiodicity_status: Status::ProvenByAlgebra,
        mahler_reduction_status: Status::ProvenByAlgebra,
        finite_checkpoints_status: Status::VerifiedForFiniteDomain,
        uncancelled_tower_status: Status::Refuted,
        cancelled_pade_exploration_status: Status::VerifiedForFiniteDomain,
        shift_and_general_divergent_status: Status::Conjectured,
        checkpoints,
        periodic_control,
        pade_candidates,
        tower_summary,
        unresolved_obligations: vec![
            "Kernel-checked formalization (e.g., in Lean 4) of the a_k^2-cancelled backward Mahler tower transport for B(z) = z^2(1 - z) and the degree-4 Padé contradiction.".into(),
            "Exclusion of arbitrary shifted itineraries w^(s)(t) = w[s + t] (s >= 1), which require a coupled 4-state inhomogeneous Mahler system rather than the unshifted scalar equation.".into(),
            "Exclusion of general non-automatic, Sturmian, or arbitrary aperiodic survivor itineraries with tau(n) = +infinity.".into(),
            "Resolution of the Coefficient Stopping Time conjecture (whether any minimal nonconvergent positive integer orbit can cross a coefficient threshold) and the Collatz conjecture itself.".into(),
        ],
    })
}
